/* ============================================================
   HELPERS
   ============================================================ */
window.forEachStudent = function (cb) {
  var data = window.STUDENTS_DATA || {};
  Object.keys(data).forEach(function (cls) {
    var sections = data[cls] || {};
    Object.keys(sections).forEach(function (sec) {
      (sections[sec] || []).forEach(function (s) {
        cb(s, cls, sec);
      });
    });
  });
};

window.findStudentById = function (id) {
  var found = null;
  window.forEachStudent(function (s, cls, sec) {
    if (s.id === id) found = { student: s, cls: cls, section: sec };
  });
  return found;
};

window.countClass = function (cls) {
  var data = window.STUDENTS_DATA || {};
  var sections = data[cls] || {};
  var total = 0;
  Object.keys(sections).forEach(function (sec) {
    total += (sections[sec] || []).length;
  });
  return total;
};

window.normalizeStudent = function (s, cls, section) {
  return {
    id:       s.id,
    roll:     s.roll,
    name:     s.name,
    father:   s.father   || '',
    mother:   s.mother   || '',
    dob:      s.dob      || '',
    religion: s.religion || '',
    gender:   s.gender   || '',
    subjects: s.subjects || '',
    year:     s.year     || window.STUDENTS_DEFAULT_YEAR,
    shift:    s.shift    || window.STUDENTS_DEFAULT_SHIFT,
    cls:      String(cls),
    section:  section
  };
};